/**
 * Generate extension/src/i18n/messages.ts from extension/_locales/<lang>/messages.json.
 * Source of truth is _locales (Chrome format: { key: { message, description } }).
 * DO NOT EDIT messages.ts by hand — edit _locales, then run:
 *   bun scripts/generate-i18n.ts   (or: bun run i18n:generate)
 * Placeholder syntax in messages is {name} (the t() syntax Otter already uses).
 * chrome.i18n.getMessage() returns the raw message; t() substitutes {name} after.
 */
import * as fs from "node:fs";
import * as path from "node:path";

const root = path.resolve(import.meta.dir, "..");
const localesDir = path.join(root, "extension", "_locales");
const outFile = path.join(root, "extension", "src", "i18n", "messages.ts");

function readLocale(lang: string): Record<string, string> {
  const file = path.join(localesDir, lang, "messages.json");
  const raw = JSON.parse(fs.readFileSync(file, "utf8")) as Record<string, { message: string }>;
  const out: Record<string, string> = {};
  for (const [key, entry] of Object.entries(raw)) {
    if (typeof entry?.message !== "string") throw new Error(`${lang}/${key}: missing message`);
    out[key] = entry.message;
  }
  return out;
}

function placeholders(message: string): string[] {
  return [...new Set([...message.matchAll(/\{([A-Za-z0-9_]+)\}/g)].map((m) => m[1]))].sort();
}

const vi = readLocale("vi");
const en = readLocale("en");
const viKeys = Object.keys(vi).sort();
const enKeys = Object.keys(en).sort();

if (JSON.stringify(viKeys) !== JSON.stringify(enKeys)) {
  const onlyVi = viKeys.filter((k) => !enKeys.includes(k));
  const onlyEn = enKeys.filter((k) => !viKeys.includes(k));
  throw new Error(`i18n parity failed. Only vi: ${onlyVi.join(", ")}. Only en: ${onlyEn.join(", ")}.`);
}
for (const key of viKeys) {
  if (!vi[key].trim() || !en[key].trim()) throw new Error(`i18n empty message: ${key}`);
  const pv = placeholders(vi[key]);
  const pe = placeholders(en[key]);
  if (JSON.stringify(pv) !== JSON.stringify(pe)) {
    throw new Error(`i18n placeholder mismatch: ${key} vi={${pv.join(",")}} en={${pe.join(",")}}`);
  }
}

const typeUnion = viKeys.map((k) => `  | ${JSON.stringify(k)}`).join("\n");
const body = `// DO NOT EDIT — generated by scripts/generate-i18n.ts from extension/_locales/<lang>/messages.json.
// Edit _locales, then run: bun scripts/generate-i18n.ts

export type TranslationKey =
${typeUnion};

export const messages: Record<"vi" | "en", Record<TranslationKey, string>> = {
  vi: ${JSON.stringify(vi, null, 2)},
  en: ${JSON.stringify(en, null, 2)},
};
`;

fs.mkdirSync(path.dirname(outFile), { recursive: true });
fs.writeFileSync(outFile, body);
console.log(`[+] i18n: generated ${outFile} with ${viKeys.length} keys (vi/en parity OK)`);
